"""Researched initial attraction records, reviewed 2026-10-24.

Opening hours may vary for holidays, worship, events, or maintenance. The source links
are provided to make these seed values auditable and easy for the administrator to update.
Coordinates refer to the attraction, not necessarily its entrance.
"""

CATEGORIES = ('Religious', 'Nature', 'Heritage', 'Cultural', 'Modern')
KADUWELA = (6.93570, 79.98433)  # OpenStreetMap Kaduwela town, not a private home.


def everyday(start, end):
    return {str(day): [[start, end]] for day in range(7)}


def temple_windows():
    return {str(day): [['06:00', '10:00'], ['17:00', '21:00']] for day in range(7)}


